#!/usr/bin/env bash
# Question 1: Cluster certificates. Generated by Quick Create; variables arrive as environment variables.
set -euo pipefail

rm -f "${Q1_EXPIRY}"
mkdir -p "$(dirname "${Q1_EXPIRY}")"
install -d -m 700 /root/.cka
openssl x509 -in /etc/kubernetes/pki/apiserver.crt -noout -enddate | cut -d= -f2 > /root/.cka/apiserver-enddate
openssl x509 -in /etc/kubernetes/pki/apiserver.crt -noout -fingerprint -sha256 > /root/.cka/apiserver-fingerprint
kubectl create namespace "${Q1_USER_NS}" >/dev/null 2>&1 || kubectl get namespace "${Q1_USER_NS}" >/dev/null
timeout 60 bash -c "until kubectl -n '${Q1_USER_NS}' get serviceaccount default >/dev/null 2>&1; do sleep 1; done"
kubectl delete csr "${Q1_USER_NAME}" --ignore-not-found >/dev/null
rm -f "${Q1_USER_KUBECONFIG}"
